// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type WealthGrowthChartProps = Record<string, any>;

const WealthGrowthChart: React.FC<WealthGrowthChartProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "Wealth Growth (US$)",
  primaryColor = "#00e5ff",
  secondaryColor = "#94a3b8",
  gridColor = "#334155",
  particleCount = 35,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout Dimensions for 9:16
  const chartWidth = 800;
  const chartHeight = 900;
  const startX = 180; 
  const startY = 550; 

  const mapX = (year: number) => (year / 20) * chartWidth;
  const mapY = (val: number) => chartHeight - (val / 1000000) * chartHeight;

  // Path Data Generators
  const line1Points: string[] = [];
  const line2Points: string[] = [];

  for (let i = 0; i <= 20; i++) {
    const x = mapX(i);
    const val1 = 10000 * Math.pow(100, i / 20); // Exponential curve ending at 1M
    const val2 = 10000 + (90000 / 20) * i;      // Linear curve ending at 100k
    line1Points.push(`${x},${mapY(val1)}`);
    line2Points.push(`${x},${mapY(val2)}`);
  }

  const path1 = `M ${line1Points.join(" L ")}`;
  const path2 = `M ${line2Points.join(" L ")}`;
  const area1Path = `${path1} L ${chartWidth},${chartHeight} L 0,${chartHeight} Z`;
  const area2Path = `${path2} L ${chartWidth},${chartHeight} L 0,${chartHeight} Z`;

  // Animation Timings
  const wipeStartFrame = 45;
  const wipeEndFrame = durationInSeconds * fps - 60;
  const wipeProgress = interpolate(
    frame,
    [wipeStartFrame, wipeEndFrame],
    [0, chartWidth],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Dynamic Leading Nodes Logic
  const currentYear = (wipeProgress / chartWidth) * 20;
  const currentVal1 = 10000 * Math.pow(100, currentYear / 20);
  const currentY1 = mapY(currentVal1);
  const currentVal2 = 10000 + (90000 / 20) * currentYear;
  const currentY2 = mapY(currentVal2);

  // Labels
  const yLabels = [
    { label: "1M+", value: 1000000 },
    { label: "500k", value: 500000 },
    { label: "100k", value: 100000 },
    { label: "50k", value: 50000 },
    { label: "10k", value: 10000 },
  ];
  const xLabels = [0, 5, 10, 15, 20];

  // Camera & Holographic Effects
  const pushInScale = interpolate(frame, [0, durationInSeconds * fps], [0.95, 1.05]);
  const translateY = interpolate(frame, [0, durationInSeconds * fps], [20, -20]);
  const titleOpacity = interpolate(frame, [0, 10, 15, 20], [0, 0.5, 0.2, 1], { extrapolateRight: "clamp" });
  
  const chartRotationX = interpolate(frame, [0, durationInSeconds * fps], [15, 5]);
  const chartRotationY = interpolate(frame, [0, durationInSeconds * fps], [-8, 0]);

  const bokehParticles = React.useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => ({
      x: random(`x-${i}`) * 120 - 10,
      y: random(`y-${i}`) * 120 - 10,
      size: random(`s-${i}`) * 100 + 20,
      opacity: random(`o-${i}`) * 0.15 + 0.05,
      speed: random(`sp-${i}`) * 0.8 + 0.2,
    }));
  }, [particleCount]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Volumetric Radial Light */}
      <div
        style={{
          position: "absolute",
          top: "-20%",
          left: "-20%",
          width: "140%",
          height: "140%",
          background: `radial-gradient(circle at ${interpolate(frame, [0, durationInSeconds * fps], [40, 60])}% ${interpolate(frame, [0, durationInSeconds * fps], [30, 70])}%, rgba(0, 229, 255, 0.15) 0%, rgba(0, 0, 0, 0) 50%)`,
          opacity: interpolate(frame, [0, 30], [0, 1]),
        }}
      />

      {/* Bokeh Particles */}
      <div style={{ position: "absolute", width: "100%", height: "100%" }}>
        {bokehParticles.map((p, i) => {
          const yPos = p.y - frame * p.speed;
          const op = p.opacity * interpolate(frame, [0, 30], [0, 1], { extrapolateRight: "clamp" });
          return (
            <div
              key={`bokeh-${i}`}
              style={{
                position: "absolute",
                left: `${p.x}%`,
                top: `${yPos}%`,
                width: p.size,
                height: p.size,
                borderRadius: "50%",
                backgroundColor: primaryColor,
                filter: "blur(30px)",
                opacity: op,
              }}
            />
          );
        })}
      </div>

      <AbsoluteFill style={{ transform: `scale(${pushInScale}) translateY(${translateY}px)` }}>
        {/* Titles & Legends */}
        <div style={{ position: "absolute", top: 150, left: 0, width: "100%", display: "flex", flexDirection: "column", alignItems: "center" }}>
          <h1
            style={{
              fontFamily: interFamily,
              fontSize: 56,
              color: "#ffffff",
              margin: 0,
              fontWeight: 700,
              letterSpacing: "-0.02em",
              textShadow: `0 0 20px rgba(255,255,255,0.3)`,
              opacity: titleOpacity,
            }}
          >
            {title}
          </h1>

          <div style={{ display: "flex", gap: 30, marginTop: 40, opacity: titleOpacity }}>
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: primaryColor, boxShadow: `0 0 12px ${primaryColor}` }} />
              <span style={{ fontFamily: interFamily, fontSize: 24, color: "#f8fafc", fontWeight: 500 }}>Compound Interest Portfolio (7% APY)</span>
            </div>
          </div>
          <div style={{ display: "flex", gap: 30, marginTop: 15, opacity: titleOpacity }}>
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: secondaryColor }} />
              <span style={{ fontFamily: interFamily, fontSize: 24, color: "#94a3b8", fontWeight: 500 }}>Standard Savings (2% APY)</span>
            </div>
          </div>
        </div>

        {/* 3D Floating Chart Environment */}
        <div
          style={{
            position: "absolute",
            left: startX,
            top: startY,
            width: chartWidth,
            height: chartHeight,
            transformStyle: "preserve-3d",
            perspective: "1200px",
            transform: `rotateX(${chartRotationX}deg) rotateY(${chartRotationY}deg)`,
          }}
        >
          {/* Layer 1: Grid & Axes */}
          <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible", transform: "translateZ(-50px)" }}>
            {yLabels.map((lbl, i) => {
              const y = mapY(lbl.value);
              const lineOpacity = interpolate(frame, [15 + i * 5, 30 + i * 5], [0, 0.4], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              const textOpacity = interpolate(frame, [15 + i * 5, 30 + i * 5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

              return (
                <g key={`y-${i}`}>
                  <line x1={0} y1={y} x2={chartWidth} y2={y} stroke={gridColor} strokeDasharray="6 6" strokeWidth={2} opacity={lineOpacity} />
                  <text x={-20} y={y + 8} fill="#94a3b8" fontSize={24} fontFamily={robotoMonoFamily} textAnchor="end" opacity={textOpacity}>{lbl.label}</text>
                </g>
              );
            })}
            {xLabels.map((val, i) => {
              const x = mapX(val);
              const opacity = interpolate(frame, [30 + i * 5, 45 + i * 5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              return (
                <g key={`x-${i}`}>
                  <line x1={x} y1={0} x2={x} y2={chartHeight} stroke={gridColor} strokeDasharray="6 6" strokeWidth={1.5} opacity={opacity * 0.2} />
                  <text x={x} y={chartHeight + 45} fill="#94a3b8" fontSize={24} fontFamily={robotoMonoFamily} textAnchor="middle" opacity={opacity}>{val}</text>
                </g>
              );
            })}
            <text x={chartWidth / 2} y={chartHeight + 100} fill="#64748b" fontSize={24} fontFamily={interFamily} textAnchor="middle" opacity={interpolate(frame, [50, 65], [0, 1], { extrapolateLeft: "clamp" })}>
              Time (Years)
            </text>
          </svg>

          {/* Layer 2: Area Fills */}
          <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible", transform: "translateZ(-20px)" }}>
            <defs>
              <clipPath id="wipeClip">
                <rect x={-20} y={-50} width={wipeProgress + 20} height={chartHeight + 100} />
              </clipPath>
              <linearGradient id="area1Grad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={primaryColor} stopOpacity={0.25} />
                <stop offset="100%" stopColor={primaryColor} stopOpacity={0.0} />
              </linearGradient>
              <linearGradient id="area2Grad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={secondaryColor} stopOpacity={0.2} />
                <stop offset="100%" stopColor={secondaryColor} stopOpacity={0.0} />
              </linearGradient>
            </defs>
            <path d={area2Path} fill="url(#area2Grad)" clipPath="url(#wipeClip)" />
            <path d={area1Path} fill="url(#area1Grad)" clipPath="url(#wipeClip)" />
          </svg>

          {/* Layer 3: Data Lines */}
          <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible", transform: "translateZ(10px)" }}>
            <defs>
              <filter id="lineGlow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation="12" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
            </defs>
            <path d={path2} fill="none" stroke={secondaryColor} strokeWidth={4} strokeLinecap="round" strokeLinejoin="round" clipPath="url(#wipeClip)" />
            <path d={path1} fill="none" stroke={primaryColor} strokeWidth={6} strokeLinecap="round" strokeLinejoin="round" clipPath="url(#wipeClip)" filter="url(#lineGlow)" />
          </svg>

          {/* Layer 4: Glowing Nodes & Highlights */}
          <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible", transform: "translateZ(40px)" }}>
            <defs>
              <filter id="nodeGlow" x="-100%" y="-100%" width="300%" height="300%">
                <feGaussianBlur stdDeviation="8" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
            </defs>

            {/* Static Nodes tracking data milestones */}
            {xLabels.map((val, i) => {
              const nodeX = mapX(val);
              const nodeY1 = mapY(10000 * Math.pow(100, val / 20));
              const passedProgress = interpolate(wipeProgress, [nodeX - 5, nodeX + 20], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              
              if (passedProgress === 0) return null;
              
              return (
                <circle
                  key={`static-node-${i}`}
                  cx={nodeX}
                  cy={nodeY1}
                  r={8 * passedProgress}
                  fill={backgroundColor}
                  stroke={primaryColor}
                  strokeWidth={3 * passedProgress}
                  filter="url(#nodeGlow)"
                  opacity={passedProgress}
                />
              );
            })}

            {/* Leading Node 2 (Subtle) */}
            {frame >= wipeStartFrame && wipeProgress < chartWidth && (
              <circle
                cx={wipeProgress}
                cy={currentY2}
                r={6}
                fill={backgroundColor}
                stroke={secondaryColor}
                strokeWidth={3}
              />
            )}

            {/* Leading Node 1 (Electric Blue) */}
            {frame >= wipeStartFrame && wipeProgress < chartWidth && (
              <circle
                cx={wipeProgress}
                cy={currentY1}
                r={10}
                fill="#ffffff"
                stroke={primaryColor}
                strokeWidth={5}
                filter="url(#nodeGlow)"
              />
            )}
          </svg>
        </div>
      </AbsoluteFill>

      {/* Holographic Scanlines Overlay */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          background: `repeating-linear-gradient(
            0deg,
            transparent,
            transparent 4px,
            rgba(255, 255, 255, 0.015) 4px,
            rgba(255, 255, 255, 0.015) 8px
          )`,
          opacity: interpolate(frame, [0, 20], [0, 1]),
          pointerEvents: "none",
          mixBlendMode: "screen",
        }}
      />
    </AbsoluteFill>
  );
};

export default WealthGrowthChart;